import React, { useState, useEffect } from 'react';
import axios from 'axios';
import '../dashboard.css';

const CustomerDashboard = ({ user, onLogout }) => {
  const [restaurants, setRestaurants] = useState([]);
  const [menuItems, setMenuItems] = useState([]);
  const [orders, setOrders] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    fetchRestaurants();
    fetchMenuItems();
    fetchOrders();
  }, []);

  const fetchRestaurants = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/restaurants');
      setRestaurants(response.data);
    } catch (error) {
      console.error('Error fetching restaurants:', error);
    }
  };

  const fetchMenuItems = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/menu-items');
      setMenuItems(response.data);
    } catch (error) {
      console.error('Error fetching menu items:', error);
    }
  };

  const fetchOrders = async () => {
    try {
      const response = await axios.get(`http://localhost:8080/api/orders/customer/${user.id}`);
      setOrders(response.data);
    } catch (error) {
      console.error('Error fetching orders:', error);
    }
  };

  const addToCart = (item) => {
    const existingItem = cart.find(cartItem => cartItem.id === item.id);
    if (existingItem) {
      setCart(cart.map(cartItem => 
        cartItem.id === item.id 
          ? { ...cartItem, quantity: cartItem.quantity + 1 }
          : cartItem
      ));
    } else {
      setCart([...cart, { ...item, quantity: 1 }]);
    }
  };

  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <h1>🍕 Welcome, {user.name}!</h1>
        <button onClick={onLogout} className="logout-btn">Logout</button>
      </div>

      <div className="dashboard-content">
        <div className="menu-section">
          <h2>Available Menu Items</h2>
          <div className="menu-grid">
            {menuItems.map(item => (
              <div key={item.id} className="menu-card">
                <h3>{item.name}</h3>
                <p>{item.description}</p>
                <div className="item-details">
                  <span className="price">${item.price}</span>
                  <span className="stock">Stock: {item.stock}</span>
                </div>
                <button 
                  onClick={() => addToCart(item)}
                  disabled={item.stock === 0}
                  className="add-btn"
                >
                  Add to Cart
                </button>
              </div>
            ))}
          </div>
        </div>

        <div className="cart-section">
          <h2>Cart ({cart.length})</h2>
          {cart.map(item => (
            <div key={item.id} className="cart-item">
              <span>{item.name} x{item.quantity}</span>
              <span>${(item.price * item.quantity).toFixed(2)}</span>
            </div>
          ))}
        </div>

        <div className="orders-section">
          <h2>My Orders</h2>
          {orders.map(order => (
            <div key={order.id} className="order-card">
              <p>Order #{order.id} - ${order.totalPrice}</p>
              <span className={`status ${order.status.toLowerCase()}`}>
                {order.status}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default CustomerDashboard;
